var total_ticks := 0
var score := 0

@onready var timer: Timer = $Ticker/Timer
@onready var score_label: Label = $ScoreUI/ScoreLabel

extends Node2D

const TICK_MESSAGE := "live tick"

@export var tick_interval: float = 1.0

var total_ticks := 0
var _paused := false

@onready var timer: Timer = $Ticker/Timer
@onready var pause_menu: CanvasLayer = $PauseMenu
@onready var resume_button: Button = $PauseMenu/CenterContainer/ResumeButton


func _ready() -> void:
	timer.wait_time = tick_interval
	timer.timeout.connect(_on_timeout)
	resume_button.text = "Resume"
	print("Gofer live test scene ready")


func _unhandled_input(_event: InputEvent) -> void:
	if Input.is_action_just_pressed("pause"):
		_paused = !_paused
		get_tree().paused = _paused
		pause_menu.visible = _paused


func _on_resume_button_pressed() -> void:
	_paused = false
	get_tree().paused = false
	pause_menu.visible = false


func _on_tick(ticks: int) -> void:
	total_ticks = ticks
	_announce(ticks)
	if ticks == 5:
		push_warning("Live test reached five ticks")


func _announce(ticks: int) -> void:
	print("%s %d" % [TICK_MESSAGE, ticks])


func _on_timeout() -> void:
	_on_tick(total_ticks + 1)

