extends CanvasLayer

var _main_node: Node2D


func _ready() -> void:
	visible = false
	_main_node = get_parent()


func _input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		var paused := not get_tree().paused
		if paused:
			visible = true
			# Defer pausing so layout runs this frame
			_main_node._pending_pause = true
		else:
			get_tree().paused = false
			visible = false


func _on_resume_button_pressed() -> void:
	get_tree().paused = false
	visible = false

